WITH with_latest AS (SELECT s.*, x.amount FROM accounts s JOIN LATERAL (SELECT c.amount FROM transactions c WHERE c.account_id = s.id ORDER BY c.amount DESC, c.id DESC LIMIT 1) x ON TRUE) SELECT id, account_type, amount, CASE WHEN account_type RLIKE '^(LOAN|SAVINGS)$' THEN 'EXTENDED' WHEN account_type RLIKE '^(CHECKING|CREDIT)$' THEN 'GROUP_B' ELSE 'CORE' END AS account_type_zone FROM with_latest ORDER BY amount;
